    await request.post('/api/cart', {
      data: { userId, item: { productId: PRODUCT_IDS.SOLAR_SYSTEM_IMAGER, quantity: 1 } },
    });

    await request.post('/api/checkout?currencyCode=USD', { data: checkoutPayload(userId) });

